const checkLength = (name: string, value: any) => {
  if (
    typeof value !== "string" ||
    !/^[+-]?(?:\d*\.\d+|\d+)(?:e[+-]?\d+)?(?:px|rem|em|ex|%|in|cm|mm|q|pt|pc)$/i.test(
      value
    )
  ) {
    throw new RangeError(`Invalid CSS length for ${name}`)
  }
}

